INSERT INTO `company_statements` (`id`, `type`, `title`, `description`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'vision', 'Vision Statement', 'To become a leading Zambian-based model in chemical-devoid large-scale farming of organic crops and medicinal plants and industrial hub for manufacturing of innovative standardized TCAMs, Nutraceuticals/Food Supplements, phytomedicines and phytopharmaceuticals subjected to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, high-nutrient organic fertilizers as well as clean-label fortified health food products and fruit beverages- recognized across African continent and globally for quality, safety and sustainability, and contribution to the sustainable socioeconomic transformation.', 'bx-show', 1, 1, '2026-03-04 12:00:44', '2026-03-04 12:42:37'),
(2, 'mission', 'Mission Statement', 'To organically do large-scale commercial farming of key medicinal plants, functional crops, fruits and vegetables in over 2000 hectare-farmland and to process the harvest into GMPcompliant and ISO standard TCAMs, Nutraceuticals/Food Supplements, phytomedicines and phytopharmaceuticals subjected to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, as well as clean-label fortified health food products and fruit beverages and high-nutrient organic fertilizers.', 'bx bx-target', 2, 1, '2026-03-04 12:00:44', '2026-03-04 13:15:43'),
(3, 'other', 'Strategic Positioning', 'AFRICAN GREEN FARMERS LIMITED is positioned as a vertically integrated agro-industrial company focused on high-value medicinal and functional crops. Through structured partnerships, value addition and export-oriented processing, the company transforms commercial organic agriculture into scalable industrial (TCAMs, Nutraceuticals/Food Supplements, phytomedicines and phytopharmaceuticals subjected to preclinical and clinical trials via our scientific research laboratory and laboratory animal breeding facility, as well as clean-label fortified health food products and fruit beverages.', 'bx-map-alt', 3, 1, '2026-03-04 12:00:44', '2026-03-04 12:00:44');

