--
-- Structure de la table `consultations`
--

CREATE TABLE `consultations` (
  `id` int(10) UNSIGNED NOT NULL,
  `patient_id` int(10) UNSIGNED NOT NULL,
  `medecin_id` int(10) UNSIGNED NOT NULL,
  `numero_consultation` varchar(50) NOT NULL,
  `type` enum('video','presentiel','telephone') DEFAULT 'video',
  `poids` decimal(5,2) DEFAULT NULL,
  `taille` decimal(5,2) DEFAULT NULL,
  `symptomes` text DEFAULT NULL,
  `duree_symptomes` varchar(50) DEFAULT NULL,
  `consultation_precedente` enum('yes','no') DEFAULT 'no',
  `examens_demandes` text DEFAULT NULL,
  `ordonnances` text DEFAULT NULL,
  `diagnostic` text DEFAULT NULL,
  `traitement` text DEFAULT NULL,
  `notes_medecin` text DEFAULT NULL,
  `date_souhaitee` datetime NOT NULL,
  `date_confirmee` datetime DEFAULT NULL,
  `date_debut` datetime DEFAULT NULL,
  `date_fin` datetime DEFAULT NULL,
  `duree_minutes` int(11) DEFAULT 30,
  `room_id` varchar(100) DEFAULT NULL,
  `room_url` varchar(500) DEFAULT NULL,
  `statut` enum('en_attente','confirmee','en_cours','terminee','annulee','refusee') DEFAULT 'en_attente',
  `honoraires_consultation` decimal(10,2) NOT NULL DEFAULT 0.00,
  `motif_annulation` varchar(255) DEFAULT NULL,
  `prix_ht` decimal(15,2) NOT NULL,
  `devise` varchar(10) DEFAULT 'USD',
  `tva` decimal(5,2) DEFAULT 20.00,
  `prix_ttc` decimal(15,2) GENERATED ALWAYS AS (`prix_ht` * (1 + `tva` / 100)) STORED,
  `paiement_statut` enum('en_attente','paye','echoue','rembourse') DEFAULT 'en_attente',
  `mode_paiement` varchar(50) DEFAULT NULL,
  `preuve_paiement` varchar(255) DEFAULT NULL,
  `ip_creation` varchar(45) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `consultations`
--

