CREATE TABLE `equipe` (
  `id_membre` int(11) NOT NULL,
  `nom` varchar(100) NOT NULL,
  `prenom` varchar(100) NOT NULL,
  `poste` varchar(150) NOT NULL,
  `biographie` text DEFAULT NULL,
  `photo_url` varchar(500) DEFAULT NULL,
