--
-- Structure de la table `facility_tree`
--

CREATE TABLE `facility_tree` (
  `id` int(11) NOT NULL,
  `parent_id` int(11) DEFAULT NULL,
  `node_level` int(11) NOT NULL COMMENT '1=Zone, 2=Section, 3=Espace, 4=Sous-espace',
  `node_code` varchar(20) DEFAULT NULL COMMENT 'I, II, III, etc.',
  `node_name` varchar(255) NOT NULL,
  `node_type` enum('zone','section','industrial_space','residential_space','garage_space','fencing','total','floor') DEFAULT 'industrial_space',
  `length_m` decimal(8,2) DEFAULT NULL,
  `width_m` decimal(8,2) DEFAULT NULL,
  `area_m2` decimal(10,2) DEFAULT NULL,
  `height_m` decimal(8,2) DEFAULT NULL,
  `storage_type` enum('standard','hs','2f','cold_room') DEFAULT 'standard',
  `has_shelves` tinyint(1) DEFAULT 0,
  `floor_level` int(11) DEFAULT NULL COMMENT '1=Rez-de-chaussée, 2=Étage 1, etc.',
  `description` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `icon_name` varchar(100) DEFAULT NULL,
  `color_code` varchar(20) DEFAULT NULL,
  `sort_order` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

