--
-- Structure de la table `faq`
--

CREATE TABLE `faq` (
  `id_faq` int(11) NOT NULL,
  `question` text NOT NULL,
  `reponse` longtext NOT NULL,
  `categorie` varchar(100) DEFAULT 'general',
  `ordre` int(11) DEFAULT 0,
  `est_publiee` tinyint(1) DEFAULT 1,
  `id_page_associee` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

--
-- Déchargement des données de la table `faq`
--

INSERT INTO `faq` (`id_faq`, `question`, `reponse`, `categorie`, `ordre`, `est_publiee`, `id_page_associee`) VALUES
(1, 'What is AGF?', 'African Green Farmers (AGF) Limited is a vertically integrated Zambian agro-industrial biotechnology enterprise engaged in commercial organic farming and manufacturing of standardized plant-based health products.', 'general', 1, 1, NULL),
(2, 'What products do you manufacture?', 'We manufacture 7 categories of products: TCAMs, Nutraceuticals, Clean-label fortified foods, Organic fertilizers, Phytomedicines, and Phytopharmaceuticals.', 'produits', 2, 1, NULL),
(3, 'Are your products GMP compliant?', 'Yes, all our products are manufactured in our GMP-compliant facility AGF-PHYTOMED INDUSTRIES.', 'qualite', 3, 1, NULL),
(4, 'How can I invest in AGF?', 'You can submit a Manifestation of Interest (MOI) through our website or contact our investor relations team.', 'investissement', 4, 1, NULL),
(5, 'Do you work with out-growers?', 'Yes, we have structured out-grower networks and plan to integrate 5,000+ out-growers by 2031, with focus on youth and women participation.', 'social', 5, 1, NULL),
(6, 'What certifications do you have?', 'We have multiple certifications including PACRA registration, ZDA Investment License, and we are in process for ISO and GMP certifications.', 'qualite', 6, 1, NULL);

