--
-- Structure de la table `galerie_medias`
--

CREATE TABLE `galerie_medias` (
  `id_media` int(11) NOT NULL,
  `titre` varchar(255) DEFAULT NULL COMMENT 'Titre du média',
  `type` enum('image','video','audio','document','link','autre') NOT NULL COMMENT 'Type de média (link = lien externe)',
  `fichier` varchar(500) DEFAULT NULL COMMENT 'Chemin du fichier uploadé (pour types image, video, audio, document, autre)',
  `lien` varchar(500) DEFAULT NULL COMMENT 'URL externe (pour type link)',
  `miniature` varchar(500) DEFAULT NULL COMMENT 'Chemin de la miniature (optionnel)',
  `description` text DEFAULT NULL COMMENT 'Description du média',
  `categorie` varchar(100) DEFAULT NULL COMMENT 'Catégorie (ex: publicité, témoignage, produit)',
  `date_media` date DEFAULT NULL COMMENT 'Date de création/prise du média',
  `credits` varchar(255) DEFAULT NULL COMMENT 'Crédits/auteur',
  `taille` int(11) DEFAULT NULL COMMENT 'Taille du fichier en octets (pour fichiers)',
  `mime_type` varchar(100) DEFAULT NULL COMMENT 'Type MIME (pour fichiers)',
  `est_actif` tinyint(1) DEFAULT 1 COMMENT '0 = caché, 1 = visible',
  `a_partager_reseaux` tinyint(1) DEFAULT 0 COMMENT '1 = à partager sur les réseaux sociaux',
  `message_reseaux` text DEFAULT NULL COMMENT 'Message personnalisé pour le partage',
  `required_subscription_id` int(10) UNSIGNED DEFAULT NULL,
  `id_page_associee` int(11) DEFAULT NULL COMMENT 'Page associée (si applicable)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `galerie_medias`
--

