(5, 'Invest in the Future', 'Phytomedicinal <span class=\"highlight\">Investment</span> Opportunities', 'Join AGF Phytomed in our mission to revolutionize natural health. Discover unique investment opportunities in research, organic agriculture, and innovative wellness solutions.', '3b675831ac1cdfc26fcea1175c2fc852.jpg', 'Become an Investor', 'bx-right-arrow-alt', 'Investors-form', NULL, NULL, NULL, 1, 1, '2026-02-24 19:28:15', '2026-03-01 17:10:58'),
(6, 'Your Natural Pharmacy', 'Our <span class=\"highlight\">Online</span> Organic Products Marketplace', 'Access our complete catalog of phytomedicinal products, dietary supplements, and natural solutions. Fast delivery, secure payment, and personalized advice included.', '9c3f4ba0e80d7ef2f7d9423c1cc7bce2.jpg', 'Visit Shop', NULL, 'Home/Boutique', 'New Arrivals', NULL, 'Home/NewArrivals', 2, 1, '2026-02-24 19:28:15', '2026-02-25 15:41:56'),
(7, 'Healthcare at a Distance', 'Expert <span class=\"highlight\">Phytotherapy</span> Teleconsultation', 'Consult our phytotherapy experts from the comfort of your home. Personalized diagnosis, natural prescription, and complete follow-up via secure video conference. Appointment booking within 24 hours.', '8f8d130aaa695ce08cc5df05799a48f0.jpg', 'Book Appointment', NULL, 'Medicins', 'Our Experts', NULL, 'Home/Experts', 3, 1, '2026-02-24 19:28:15', '2026-02-25 15:41:13');

