CREATE TABLE `prescriptions` (
  `id` int(10) UNSIGNED NOT NULL,
  `consultation_id` int(10) UNSIGNED NOT NULL,
  `medicament` varchar(255) NOT NULL,
  `dosage` varchar(100) DEFAULT NULL,
