  `titre_section` varchar(255) DEFAULT NULL,
  `sous_titre` mediumtext DEFAULT NULL,
  `contenu_texte` longtext DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `image_droite` tinyint(1) DEFAULT 0,
  `bouton_texte` varchar(100) DEFAULT NULL,
  `bouton_lien` varchar(500) DEFAULT NULL,
  `ordre` int(11) DEFAULT 0,
