INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `sous_titre`, `contenu_texte`, `image_url`, `image_droite`, `bouton_texte`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(38, 1, 'image_texte', 'Consult a Healthcare Professional, Wherever You Are', 'Simple, Fast, and Secure Teleconsultation with Qualified Agents at Your Service', '<p>Access reliable and secure teleconsultation services in just a few clicks. Our platform connects you with qualified agents and healthcare professionals who are available to respond to your needs quickly and efficiently. Whether you need medical advice, follow-up care, or guidance, we support you remotely with confidentiality and professionalism. Avoid unnecessary travel and long waiting times: book your appointment online and consult from the comfort of your home, anytime. Our priority is to provide you with an accessible, human</p>', '/attachments/Sections/2026022713194869a17dd42b5fc.jpg', 0, 'Prendre Rendez-Vous', 'Medicins', 3, '2026-03-01 15:44:36', 'primary', NULL, '2026-03-02 13:22:25', NULL, 1),
(58, 2, 'hero', '', 'AGF-PHYTOMED INDUSTRIES', '', '/attachments/Sections/2026030119144869a47408b4280.jpg', 0, '', '', 1, '2026-03-01 15:44:36', '', NULL, '2026-03-02 14:57:59', NULL, 1),
(111, 3, 'texte', 'Background & Strategic Rationale', 'Background & Strategic Rationale ', '<p class=\"MsoNormal\" style=\"margin: 0cm 3.75pt .85pt -.25pt;\"><span style=\"font-size: 14pt;\">Zambia, like many African nations, is endowed with a rich biodiversity of medicinal plants and a strong cultural heritage of traditional medicine use. However, the Traditional, Complementary and Alternative Medicines (TCAMs) sector remains largely underdeveloped, characterized by rudimentary practices, lack of standardization, minimal research support, and the absence of modern manufacturing infrastructure. Despite growing political will, recognition by the Ministry of Health, and the establishment of regulatory bodies such as ZAMRA, the country still lacks the necessary technological capacity to transform traditional herbal knowledge into high-quality, safe, and standardized health products.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .65pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">African Green Farmers Limited is structured, via its AGF-PHYTOMED Industries Facility, as a vertically integrated, GMP-aligned and ISO standard agro-biotechnology and phytopharmaceutical manufacturing platform designed to capture high-growth demand for plant-based preventive and therapeutic health products across domestic and regional markets. By scaling commercial organic cultivation from 90 hectares to over 2,000 hectares of high-value medicinal and nutrient-dense crops, including Aloe vera and Carica papaya, and deploying USD 40+ million into advanced processing infrastructure, cleanroom manufacturing environments, phytochemical and microbiological laboratories, and ISOcertified quality systems, AGF secures raw material traceability, establishes strong barriers to entry, optimizes value addition margins, and reduces regional import dependency. The diversified product architecture&mdash;spanning standardized <span style=\"font-family: \'Calibri\',sans-serif; mso-fareast-font-family: Calibri;\">TCAMs</span>, nutraceuticals, clean-label fortified functional foods, high-nutrient organic fertilizers, clinically validated phytomedicines and phytopharmaceuticals&mdash;creates layered revenue streams with early cash-flow generation and long-term high-margin phytopharmaceutical positioning, targeting multi-million-dollar annual turnover, sustainable EBITDA performance, and scalable export expansion by 2031.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .9pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">AGF-PHYTOMED INDUSTRIES facility emerges as one of leading Zambian private initiatives to implement state-of-the-art, fully integrated and automated industrial solutions in the herbal and nutraceutical sector. The company has adopted rare customized and automated Advanced GMP-Compliant and ISO- standards Turnkey Production Complex for Herbal API (<span style=\"background: #FBD4B4;\">Active Pharmaceutical Ingredients</span>) Extraction, Encapsulation and Tableting line system. This complex industrial-scale and automated setup ―<em style=\"mso-bidi-font-style: normal;\">TURNKEY </em></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm 1.6pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\"><em style=\"mso-bidi-font-style: normal;\">ULTRASOUND-ASSISTED EXTRACTION (UAE), CAPSULE PRODUCTION AND </em></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\"><em style=\"mso-bidi-font-style: normal;\">TABLETING LINE SYSTEM</em>‖ combines three advanced processing techniques:<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .05pt 0cm;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">1)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Phyotochemical Extraction and Purification Process- Post-harvest processing, eventual defatting, concentration, eventual purification. vacuum drying and packaging the extract for storage;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">2)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Capsule Manufacturing Process- Encapsulation, bottle filling, capping and sealing, bottle instructional labeling, bottle cartoning, leaflet<span style=\"mso-spacerun: yes;\">&nbsp; </span>inserting and sealing and case packaging of 15 bottles;<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -18.0pt; mso-list: l0 level1 lfo1; margin: 0cm 0cm .85pt 18.0pt;\"><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%;\"><span style=\"mso-list: Ignore;\">3)<span style=\"font-style: normal; font-variant: normal; font-weight: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\">&nbsp;&nbsp;&nbsp; </span></span></span><!--[endif]-->Tablet Manufacturing Process- Dry extract blending, granulation, eventual vacuum drying, fluid bed dryer, tablet compression, tablet coating, bottle filing, capping, bottle sealing,<span style=\"mso-spacerun: yes;\">&nbsp; </span>bottle instructional labeling, bottle cartoning, instructional leaflet inserting as well as the case packaging of 15 bottles.<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .0001pt 18.0pt;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm .85pt -.25pt;\"><span style=\"font-size: 14pt;\">The line system operates at reduced temperatures (40&ndash;60&deg;C) to preserve heat-sensitive active pharmaceutical ingredients (Bioactive compounds) targeted to develop biologically safe and effective herbal medicines, Nutraceuticals, nutrient-dense fortified health food products and high-nutrient organic fertilizer&mdash;unprecedented cutting-edge technology in Zambia&rsquo;s TCAM/phytomedicine sector.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"color: red;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>', NULL, 0, '', '', 1, '2026-03-01 15:44:36', '', NULL, '2026-03-02 20:30:19', NULL, 1);
INSERT INTO `sections_contenu` (`id_section`, `id_page`, `type_section`, `titre_section`, `sous_titre`, `contenu_texte`, `image_url`, `image_droite`, `bouton_texte`, `bouton_lien`, `ordre`, `created_at`, `custom_class`, `options_json`, `updated_at`, `deleted_at`, `est_active`) VALUES
(112, 4, 'texte', 'ESG & Sustainability', '', '<h2 style=\"margin-left: -0.25pt; padding-left: 120px;\"><span style=\"font-size: 18pt;\">(1)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Governance, Compliance &amp; Transparency</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<h3 class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 80px;\"><span style=\"font-size: 14pt;\">AGF is committed to strong corporate governance, regulatory compliance, and financial transparency as foundational pillars of sustainable industrial growth.<strong style=\"mso-bidi-font-weight: normal;\"> </strong>The USD 40+ million capital deployment as seed capital prioritizes GMP (Good Manufacturing Practice)compliant infrastructure, ISO certification systems (<span style=\"line-height: 103%;\">ISO 9001, 22000, 14001, 45001 and 14644</span>), maintenance of annual independent financial audits, ESG (Environmental, Social and Governance) performance reporting, risk management oversight, and board-level governance structures, ensuring accountability and institutional integrity.<strong style=\"mso-bidi-font-weight: normal;\"> </strong></span></h3>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<h5 class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 320px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em><span style=\"font-size: 14pt;\">Governance Commitments:</span></em></span></h5>\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]--><strong><span style=\"font-family: georgia, palatino, serif;\">Full GMP implementation and documentation</span></strong></span></em></span></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->ISO certification roadmap completion</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Annual independent financial audits</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->ESG performance monitoring and reporting</span></em></span></strong></li>\r\n<li style=\"font-family: georgia, palatino, serif; font-weight: bold;\"><strong><span style=\"font-family: georgia, palatino, serif;\"><em><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><!--[endif]-->Structured compliance and risk management systems</span></em></span></strong></li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<h2 style=\"margin-left: -0.25pt; padding-left: 80px;\"><span style=\"font-size: 18pt;\">(2)<span style=\"font-family: \'Arial\',sans-serif; mso-fareast-font-family: Arial;\"> </span>Institutional Oversight and Accountability</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">AGF Company operates under a structured corporate governance model that assures;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.55pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Clear separation between shareholders, Boards, and Executive Management</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.4pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Defined fiduciary responsibilities and delegated authority frameworks</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.4pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Independent advisory expertise in regulatory science, finance, ESG and risk management</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.45pt; margin: 0cm 0cm 7.15pt 27pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->Structured board oversight on strategy, compliance and capital allocation</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">This governance framework aligns with international best practices recognized by institutions such as International Finance Corporation and the World Bank.</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 200px;\" align=\"left\"><span style=\"font-size: 14pt;\">&nbsp;</span></p>\r\n<h2 style=\"margin-left: -0.25pt; padding-left: 80px;\"><span style=\"font-size: 18pt;\">(2) Regulatory Compliance, Quality Assurance &amp; Licensing</span></h2>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.0001pt; text-align: left; text-indent: 0cm; line-height: 107%; padding-left: 80px;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm 0cm 0.85pt -0.25pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\">AGF is building an integrated compliance ecosystem aligned with international recognized standards, including but not limited to:</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.4pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 9001-Quality Management System</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.4pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 22000-Food Safety Management</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.5pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !supportLists]--><span style=\"mso-bidi-font-size: 14.0pt; line-height: 103%; font-family: Wingdings; mso-fareast-font-family: Wingdings; mso-bidi-font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&sect;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]-->ISO 14001- Environmental Governance and Sustainability</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"text-indent: -13.6pt; margin: 0cm 0cm 7.3pt 27.15pt; padding-left: 200px;\"><strong><span style=\"font-size: 14pt;\"><!-- [if !