--
-- Structure de la table `users`
--

CREATE TABLE `users` (
  `id` int(10) UNSIGNED NOT NULL,
  `uuid` char(36) NOT NULL,
  `email` varchar(100) NOT NULL,
  `password` varchar(255) NOT NULL,
  `nom` varchar(50) NOT NULL,
  `prenom` varchar(50) NOT NULL,
  `telephone` varchar(20) DEFAULT NULL,
  `date_naissance` date DEFAULT NULL,
  `genre` enum('M','F','Autre') DEFAULT NULL,
  `photo` varchar(255) DEFAULT 'default-avatar.png',
  `role_id` int(10) UNSIGNED NOT NULL,
  `type_utilisateur` enum('admin','medecin','patient','entreprise','investisseur','partenaire','broker') DEFAULT 'entreprise',
  `nom_entreprise` varchar(100) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `email_verified_at` datetime DEFAULT NULL,
  `email_verification_token` varchar(255) DEFAULT NULL,
  `two_factor_secret` varchar(255) DEFAULT NULL,
  `two_factor_enabled` tinyint(1) DEFAULT 0,
  `last_login_at` datetime DEFAULT NULL,
  `last_login_ip` varchar(45) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `deleted_at` timestamp NULL DEFAULT NULL,
  `secteur_activite` varchar(100) DEFAULT NULL,
  `numero_registre_commerce` varchar(50) DEFAULT NULL,
  `interet_investissement` decimal(15,2) DEFAULT NULL,
  `est_verifie` tinyint(1) DEFAULT 0 COMMENT 'Vérification KYC entreprise'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

