--
-- Structure de la table `user_activities`
--

CREATE TABLE `user_activities` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED DEFAULT NULL,
  `action` varchar(100) NOT NULL COMMENT 'Type d''action (login, logout, create, update, delete, view, etc.)',
  `module` varchar(50) DEFAULT NULL COMMENT 'Module concerné (users, produits, commandes, etc.)',
  `item_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'ID de l''élément concerné',
  `item_name` varchar(255) DEFAULT NULL COMMENT 'Nom de l''élément concerné',
  `description` text DEFAULT NULL COMMENT 'Description détaillée de l''action',
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `old_data` longtext DEFAULT NULL COMMENT 'Anciennes données (JSON)',
  `new_data` longtext DEFAULT NULL COMMENT 'Nouvelles données (JSON)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

