--
-- Structure de la table `user_subscriptions`
--

CREATE TABLE `user_subscriptions` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL COMMENT 'Référence vers users.id',
  `plan_id` int(10) UNSIGNED NOT NULL,
  `date_debut` datetime NOT NULL,
  `date_fin` datetime NOT NULL,
  `statut` enum('actif','expire','annule') NOT NULL DEFAULT 'actif',
  `prix_applique` decimal(15,2) NOT NULL COMMENT 'Prix payé',
  `devise_appliquee` varchar(10) NOT NULL,
  `pays_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'Pays de l’utilisateur à la souscription',
  `payment_method` varchar(50) DEFAULT NULL,
  `transaction_id` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

