--
-- Structure de la table `workflow_categories`
--

CREATE TABLE `workflow_categories` (
  `id_workflow` int(11) NOT NULL,
  `id_categorie` int(11) NOT NULL,
  `etape_ordre` int(11) NOT NULL DEFAULT 1,
  `nom_etape` varchar(100) NOT NULL,
  `description_etape` text DEFAULT NULL,
  `type_etape` enum('soumission','validation','production','controle_qualite','conditionnement','stockage','expedition','livraison','facturation','archive') NOT NULL DEFAULT 'soumission',
  `responsable_role` varchar(100) DEFAULT NULL,
  `delai_heures` int(11) DEFAULT NULL,
  `est_obligatoire` tinyint(1) NOT NULL DEFAULT 1,
  `notification_email` tinyint(1) NOT NULL DEFAULT 1,
  `icone_etape` varchar(50) DEFAULT 'arrow-right',
  `couleur_etape` varchar(20) DEFAULT '#0f4c3a',
  `est_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `workflow_categories`
--

INSERT INTO `workflow_categories` (`id_workflow`, `id_categorie`, `etape_ordre`, `nom_etape`, `description_etape`, `type_etape`, `responsable_role`, `delai_heures`, `est_obligatoire`, `notification_email`, `icone_etape`, `couleur_etape`, `est_active`, `created_at`, `updated_at`) VALUES
(7, 1, 1, 'CRUDE AND PURIFIED EXTRACTS PROCESSING WORKFLOW: ', '<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><!-- [if !supportLists]--><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--> <span style=\"line-height: 103%;\">TCAMs (Traditional, Complementary, and Alternative Medicines) </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><!-- [if !supportLists]--><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--><span style=\"line-height: 103%;\">Nutraceuticals/Food Supplements </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><!-- [if !supportLists]--><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--><span style=\"line-height: 103%;\">Phytomedicines </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -13.45pt; line-height: 103%; mso-list: l0 level1 lfo1; margin: 0cm 0cm .7pt 30.15pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><!-- [if !supportLists]--><span style=\"line-height: 103%; font-family: Wingdings;\"><span style=\"mso-list: Ignore;\">&Oslash;<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal; font-family: \'Times New Roman\'; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-language-override: normal; font-feature-settings: normal; font-variation-settings: normal;\"> </span></span></span><!--[endif]--><span style=\"line-height: 103%;\">Phytopharmaceuticals </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 107%;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">With our customized, fully integrated and automated Turnkey Ultrasound-Assisted Extraction (UAE), Capsule Production, Tableting and Packaging Line System: </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 107%;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 1: Papaya Leaf Powder reception and inspection </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 2: Degreasing </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 119.95pt .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 3: Extraction of target bioactive compounds using specific organic solvent Step 4: Concentration </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 5: Chromatographic purification </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 6: Vacuum drying </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 7: Micronization and ultrasonic vibratory sieving<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 8: Anti-cracking agent aseptic incorporation </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 9: Initial profiling and standardization </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 10: Capsule processing/tableting </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 11: Bottle filling, capping and sealing </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 12: Instructional labeling </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 13: Cartoning and leaflet inserting </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 14: Case packaging </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 15: Post-packaging High Pressure Processing (HPP) Optimization (Non-thermal sterilization) </span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 16: Production profiling and standardization<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 14pt;\"><strong><span style=\"line-height: 103%;\">Step 17: Inspection, palletizing and dispatch </span></strong></span></p>', 'soumission', NULL, NULL, 1, 1, 'arrow-right', '#0f4c3a', 1, '2026-03-03 15:17:11', NULL),
(8, 3, 2, 'INSTANT FORTIFIED SOYMILK POWDER PROCESSING WORKFLOW: ', '<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">With our customized, fully integrated and automated Turnkey Line System designed specifically for Fortified Liquid Soybean Milk, Soymilk Powder and Fortified Tofu: </span></p>\r\n<p class=\"MsoNormal\" style=\"margin: 0cm; margin-bottom: .0001pt; text-align: left; text-indent: 0cm; line-height: 107%;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 107%;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 1: Raw materials (Dry soybeans) reception and inspection </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 2: Cleaning, grading and sorting </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 3: Dehulling and soaking </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 4: Wet grinding<span style=\"mso-spacerun: yes;\">&nbsp; </span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 5: Slurry heating </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 6: Filtration (Okra separation) </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 7: Enzymatic deactivation </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 8: Homogenization </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 9: Initial profiling and standardization </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: -36.0pt; line-height: 103%; margin: 0cm 0cm .7pt 35.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 10: Ultra-High Pressure Processing (HPP) Optimization (Post-harvest) at 40&deg;C (Temperature) and 400600 MPa (Pressure). for microbial control before the processing takes place </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; text-indent: 0cm; line-height: 107%; margin: 0cm 0cm .7pt 0cm;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 107%;\"><span style=\"mso-spacerun: yes;\">&nbsp;</span></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 11: Initial profiling and Initial standardization </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 12: Vacuum drying into fine powder </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 31.65pt .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 13: Jet milling (Micronizer) for micronization into ultrafine powder (1-10 micrometers (Increased<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>surface area, better homogeneity, improved stability, enhanced absorption) Step 14: Ultrasonic vibratory sieving (Vibrating Screen Classifer) and cooling </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 15: Anti-caking agent incorporation (e. g. silicon dioxide) with High-Snear mixer </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 99%; margin: 0cm .6pt .15pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 99%;\">Step16: Aseptic micronutrient fortification (<em style=\"mso-bidi-font-style: normal;\">Vitamins A, B-complex, C, D and E, Omega-3, zinc,<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp; </span><span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>selenium, magnesium, cysteine</em>,, etc., natural flavoring agents)<em style=\"mso-bidi-font-style: normal;\"> </em></span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 17: Final product profiling and micronutrient standardization </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 18: Aseptic filling<strong style=\"mso-bidi-font-weight: normal;\"> </strong>into 250g, 500g and 1kg tinplate milk cans with EOE &amp; plastic overcap </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 19: Nitrogen flashing and can sealing </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 20: Instructional labeling &amp; batch coding </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 26.05pt .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 11: Post-packaging sterilization with Ultra-High Pressure Processing (HPP) Optimization for high-<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>risk products, to maximize safety with regard to pathogen content of the finished products Step 22: Case packaging (6 cans/box) </span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: left; line-height: 103%; margin: 0cm 0cm .7pt -.25pt;\" align=\"left\"><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%;\">Step 23: Plastic crate packaging </span></p>\r\n<p><span style=\"font-size: 12.0pt; mso-bidi-font-size: 11.0pt; line-height: 103%; font-family: \'Times New Roman\',serif; mso-fareast-font-family: \'Times New Roman\'; color: black; mso-ansi-language: FR; mso-fareast-language: FR; mso-bidi-language: AR-SA;\">Step 24: Inspection, palletizing and dispatch</span></p>', 'soumission', NULL, NULL, 1, 1, 'arrow-right', '#0f4c3a', 1, '2026-03-03 15:22:31', NULL),
